from collections import Counter, defaultdict
data = [("drama", 4, 5), ("drama", 4, 4), ("drama", 5, 3),
        ("comedy", 1, 2), ("comedy", 5, 4)]   # (G, R1, R2)
norm = lambda c: {k: round(v / sum(c.values()), 4) for k, v in sorted(c.items())}

def fit(shared):
    c_g, c_r1, c_r2 = Counter(), defaultdict(Counter), defaultdict(Counter)
    for g, r1, r2 in data:
        c_g[g] += 1
        c_r1[g][r1] += 1
        (c_r1 if shared else c_r2)[g][r2] += 1   # 공유면 같은 표에 쓴다
    out = {"p_G": norm(c_g), "p_R1": {g: norm(c) for g, c in c_r1.items()}}
    if not shared:
        out["p_R2"] = {g: norm(c) for g, c in c_r2.items()}
    return out

for k, v in fit(shared=False).items():
    print("[따로]", k, v)
for k, v in fit(shared=True).items():
    print("[공유]", k.replace("p_R1", "p_R"), v)

from collections import defaultdict
from copy import deepcopy

def new_counts():
    return defaultdict(lambda: defaultdict(lambda: defaultdict(float)))

def supervised_learning(structure, data, pseudo=None):
    # counts[파라미터 이름][부모 값 튜플][자기 값] = 횟수
    counts = deepcopy(pseudo) if pseudo is not None else new_counts()
    for x in data:
        for var, value in x.items():
            name, parents = structure[var]
            pv = tuple(x[p] for p in parents)
            counts[name][pv][value] += 1
    return {name: {pv: {v: c / sum(cs.values()) for v, c in cs.items()}
                   for pv, cs in by_pv.items()}
            for name, by_pv in counts.items()}

hmm = {"H1": ("start", []), "H2": ("trans", ["H1"]), "H3": ("trans", ["H2"]),
       "E1": ("emit", ["H1"]), "E2": ("emit", ["H2"]), "E3": ("emit", ["H3"])}
data = [{"H1": 0, "E1": 0, "H2": 1, "E2": 1, "H3": 0, "E3": 0},
        {"H1": 0, "E1": 1, "H2": 0, "E2": 1, "H3": 0, "E3": 1}]
theta = supervised_learning(hmm, data)
for name, t in theta.items():
    print(name, {pv: {v: round(p, 4) for v, p in sorted(d.items())} for pv, d in sorted(t.items())})

import numpy as np
from c13 import em_step                         # 바로 앞 장의 함수
data = [(1, 1)] * 4 + [(2, 2)] * 2 + [(1, 2), (2, 1)]

def run(p_g, p_r, iters=10):
    for _ in range(iters):
        p_g, p_r, _, ll = em_step(data, p_g, p_r)
    return p_g.round(4).tolist(), p_r.round(4).tolist(), round(float(ll), 4)

print("강의 초기값    ", run(np.array([.5, .5]), np.array([[.6, .4], [.4, .6]])))
print("이름 바꾼 초기값", run(np.array([.5, .5]), np.array([[.4, .6], [.6, .4]])))
print("대칭 초기값    ", run(np.array([.5, .5]), np.array([[.5, .5], [.5, .5]])))
